        public static UnityEngine.Object[] CreateTransientCabFlightController(DragonCharacter liveActor,string speciesId)
        {
            if(!Application.isPlaying)throw new InvalidOperationException("This entry is the real native PlayMode profile; use the explicit recipe entry for stopped native geometry sweeps.");
            return CreateTransientCabFlightControllerRecipe(liveActor,speciesId,30,15,0);
        }
        public static UnityEngine.Object[] CreateTransientCabFlightControllerRecipe(DragonCharacter liveActor,string speciesId,float neckPitch,float headPitch,float wingDihedral)
        {return CreateTransientCabFlightControllerCore(liveActor,speciesId,neckPitch,headPitch,wingDihedral,false,1);}
        public static UnityEngine.Object[] CreateTransientCabFlightEnvelope(DragonCharacter liveActor,string speciesId,float sourceRootFlapFraction)
        {
            if(sourceRootFlapFraction!=.25f&&sourceRootFlapFraction!=.5f)throw new InvalidOperationException("Actual source-motion envelope retains25or50percent root flap plus all original distal articulation.");
            return CreateTransientCabFlightControllerCore(liveActor,speciesId,speciesId=="dragon-inferno"?45:15,speciesId=="dragon-inferno"?0:30,0,true,sourceRootFlapFraction);
        }
        public static UnityEngine.Object[] CreateTransientSafeMountedController(DragonCharacter actor,string speciesId)
        {return CreateTransientCabFlightControllerCore(actor,speciesId,speciesId=="dragon-inferno"?45:15,speciesId=="dragon-inferno"?0:30,0,true,speciesId=="dragon-inferno"?.25f:.5f,true);}
        public static UnityEngine.Object[] CreateTransientBreathFlexCandidate(DragonCharacter actor,string speciesId,float extraNeck2,float extraDistal)
        {
            bool allowed=speciesId=="dragon-inferno"&&((extraNeck2==0&&(extraDistal==15||extraDistal==30))||(extraNeck2==15&&extraDistal==15)||(extraNeck2==30&&extraDistal==0))||speciesId=="dragon-fire"&&extraNeck2==0&&(extraDistal==10||extraDistal==20||extraDistal==30);if(!allowed||actor.motor.animator.runtimeAnimatorController is not AnimatorOverrideController source||!source.name.EndsWith("_SAFE_ACTIONS",StringComparison.Ordinal))throw new InvalidOperationException("Explicit bounded Breath-only flexion over the genuine already-generated safe action controller required.");return CreateTransientCabFlightControllerCore(actor,speciesId,speciesId=="dragon-inferno"?45:15,speciesId=="dragon-inferno"?0:30,0,true,speciesId=="dragon-inferno"?.25f:.5f,true,extraNeck2,extraDistal,true);
        }
        static DragonAnimationAction[] MountedPostureActions(DragonSpeciesDefinition species)
        {
            // Fire is a flying-only source rig: its authored ground fallback is
            // already the normal FlyIdle leaf, not nonexistent ground clips.
            var actions=new List<DragonAnimationAction>();
            if(species.Supports(DragonSpeciesRole.Ground))actions.AddRange(new[]{DragonAnimationAction.GroundIdle,DragonAnimationAction.Walk,DragonAnimationAction.Run});
            actions.AddRange(new[]{DragonAnimationAction.Takeoff,DragonAnimationAction.Land,DragonAnimationAction.Dive,DragonAnimationAction.TurnLeft,DragonAnimationAction.TurnRight,DragonAnimationAction.Breath});
            return actions.ToArray();
        }
